import zeros = require( '@stdlib/ndarray/zeros' );
import scopy = require( './index' );


// TESTS //

// The function returns an ndarray...
{
	scopy( zeros( [ 10 ], { 'dtype': 'float32' } ), zeros( [ 10 ], { 'dtype': 'float32' } ) ); // $ExpectType float32ndarray
}

// The compiler throws an error if the function is provided a first argument which is not an ndarray...
{
	const y = zeros( [ 10 ], { 'dtype': 'float32' } );

	scopy( 10, y ); // $ExpectError
	scopy( '10', y ); // $ExpectError
	scopy( true, y ); // $ExpectError
	scopy( false, y ); // $ExpectError
	scopy( null, y ); // $ExpectError
	scopy( undefined, y ); // $ExpectError
	scopy( {}, y ); // $ExpectError
	scopy( [], y ); // $ExpectError
	scopy( ( x: number ): number => x, y ); // $ExpectError

	scopy( 10, y, -1 ); // $ExpectError
	scopy( '10', y, -1 ); // $ExpectError
	scopy( true, y, -1 ); // $ExpectError
	scopy( false, y, -1 ); // $ExpectError
	scopy( null, y, -1 ); // $ExpectError
	scopy( undefined, y, -1 ); // $ExpectError
	scopy( {}, y, -1 ); // $ExpectError
	scopy( [], y, -1 ); // $ExpectError
	scopy( ( x: number ): number => x, y, -1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not an ndarray...
{
	const x = zeros( [ 10 ], { 'dtype': 'float32' } );

	scopy( x, 10 ); // $ExpectError
	scopy( x, '10' ); // $ExpectError
	scopy( x, true ); // $ExpectError
	scopy( x, false ); // $ExpectError
	scopy( x, null ); // $ExpectError
	scopy( x, undefined ); // $ExpectError
	scopy( x, {} ); // $ExpectError
	scopy( x, [] ); // $ExpectError
	scopy( x, ( x: number ): number => x ); // $ExpectError

	scopy( x, 10, -1 ); // $ExpectError
	scopy( x, '10', -1 ); // $ExpectError
	scopy( x, true, -1 ); // $ExpectError
	scopy( x, false, -1 ); // $ExpectError
	scopy( x, null, -1 ); // $ExpectError
	scopy( x, undefined, -1 ); // $ExpectError
	scopy( x, {}, -1 ); // $ExpectError
	scopy( x, [], -1 ); // $ExpectError
	scopy( x, ( x: number ): number => x, -1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a third argument which is not a number...
{
	const x = zeros( [ 10 ], { 'dtype': 'float32' } );
	const y = zeros( [ 10 ], { 'dtype': 'float32' } );

	scopy( x, y, '10' ); // $ExpectError
	scopy( x, y, true ); // $ExpectError
	scopy( x, y, false ); // $ExpectError
	scopy( x, y, null ); // $ExpectError
	scopy( x, y, {} ); // $ExpectError
	scopy( x, y, [] ); // $ExpectError
	scopy( x, y, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const x = zeros( [ 10 ], { 'dtype': 'float32' } );
	const y = zeros( [ 10 ], { 'dtype': 'float32' } );

	scopy(); // $ExpectError
	scopy( x ); // $ExpectError
	scopy( x, y, -1, {} ); // $ExpectError
}
